import api from "../global/apiHelper";
import { fetchLimit, toPage } from "../global/paged";
import useApi from "../global/useApi";

// The token is attached by the apiHelper interceptor.
// A tender looks like { id, tenant_id, reference_no, title, description, is_active }.
// The reference number (e.g. TND-0001) is generated by the backend. Super Admin only.

/**
 * GET /tenders/ — one page of tenders as { items, hasNext } (the backend sends a plain array
 * with no total). Optional: tenantId, skip, limit (max 500), activeOnly (the backend defaults it
 * to true, so deleted tenders are hidden).
 */
export const getTenders = async ({ tenantId, skip = 0, limit = 10, activeOnly } = {}) =>
  toPage(
    await api.get("/tenders/", {
      params: {
        tenant_id: tenantId,
        skip,
        limit: fetchLimit(limit),
        active_only: activeOnly,
      },
    }),
    limit,
  );

/** GET /tenders/{id}. */
export const getTender = (id) => api.get(`/tenders/${id}`);

/** POST /tenders/ with { tenantId, title, description? }. Returns the created tender. */
export const createTender = ({ tenantId, title, description }) =>
  api.post("/tenders/", { tenant_id: tenantId, title, description });

/** PUT /tenders/{id} — any of { title, description }. The tenant cannot be changed. */
export const updateTender = (id, { title, description } = {}) =>
  api.put(`/tenders/${id}`, { title, description });

/** DELETE /tenders/{id} — soft delete (204, no body). */
export const deleteTender = (id) => api.delete(`/tenders/${id}`);

export const useTenders = () => useApi(getTenders);
export const useCreateTender = () => useApi(createTender);
export const useUpdateTender = () => useApi(updateTender);
export const useDeleteTender = () => useApi(deleteTender);
